class AuthManager{constructor(){this.checkAuthStatus();this.addLogoutButton();}checkAuthStatus(){const isAdmin=sessionStorage.getItem('admin_authenticated')==='true';const authTime=sessionStorage.getItem('admin_auth_time');const currentTime=Date.now();if(isAdmin&&authTime&&(currentTime-parseInt(authTime))<14400000){this.showAdminButtons();this.showLogoutButton();}else{this.hideAdminButtons();this.hideLogoutButton();if(authTime&&(currentTime-parseInt(authTime))>=14400000){this.logout();}}}authenticate(password){if(password==='tlm@TLM'){sessionStorage.setItem('admin_authenticated','true');sessionStorage.setItem('admin_auth_time',Date.now().toString());this.showAdminButtons();this.showLogoutButton();return true;}return false;}logout(){sessionStorage.removeItem('admin_authenticated');sessionStorage.removeItem('admin_auth_time');this.hideAdminButtons();this.hideLogoutButton();if(window.location.pathname.includes('admin.html')){window.location.href='navigation.html';}}isAdmin(){const isAuth=sessionStorage.getItem('admin_authenticated')==='true';const authTime=sessionStorage.getItem('admin_auth_time');const currentTime=Date.now();if(isAuth&&authTime&&(currentTime-parseInt(authTime))>=14400000){this.logout();return false;}return isAuth;}showAdminButtons(){document.body.classList.add('admin-authenticated');if(typeof addAdminButtonsToImages==='function'){addAdminButtonsToImages();}console.log('🔓 Boutons admin activés');}hideAdminButtons(){document.body.classList.remove('admin-authenticated');document.querySelectorAll('.delete-btn').forEach(btn=>btn.remove());console.log('🔒 Boutons admin masqués');}adminAction(callback){if(this.isAdmin()){callback();}else{alert('🔐 Action réservée aux administrateurs.\nConnectez-vous d\'abord via la page Administration.');}}addLogoutButton(){if(document.getElementById('adminLogoutBtn'))return;const logoutBtn=document.createElement('div');logoutBtn.id='adminLogoutBtn';logoutBtn.className='admin-logout-btn';logoutBtn.style.display='none';logoutBtn.innerHTML=`<button onclick="authManager.logout()" class="logout-btn" title="Déconnexion administrateur">🚪 Déconnexion Admin</button>`;const style=document.createElement('style');style.textContent=` .admin-logout-btn{position: fixed;top: 20px;right: 20px;z-index: 1000;}.logout-btn{background: linear-gradient(135deg,#dc3545 0%,#c82333 100%);color: white;border: none;padding: 0.6rem 1rem;border-radius: 8px;cursor: pointer;font-size: 0.9rem;font-weight: 500;box-shadow: 0 2px 10px rgba(220,53,69,0.3);transition: all 0.3s ease;}.logout-btn:hover{background: linear-gradient(135deg,#c82333 0%,#a71e2a 100%);transform: translateY(-2px);box-shadow: 0 4px 15px rgba(220,53,69,0.4);}`;document.head.appendChild(style);document.body.appendChild(logoutBtn);}showLogoutButton(){const btn=document.getElementById('adminLogoutBtn');if(btn)btn.style.display='block';}hideLogoutButton(){const btn=document.getElementById('adminLogoutBtn');if(btn)btn.style.display='none';}getSessionTimeRemaining(){const authTime=sessionStorage.getItem('admin_auth_time');if(!authTime)return 0;const elapsed=Date.now()-parseInt(authTime);const remaining=14400000-elapsed;return Math.max(0,remaining);}formatTimeRemaining(){const remaining=this.getSessionTimeRemaining();const hours=Math.floor(remaining/3600000);const minutes=Math.floor((remaining % 3600000)/60000);return `${hours}h ${minutes}m`;}}const authManager=new AuthManager();document.addEventListener('DOMContentLoaded',function(){authManager.checkAuthStatus();if(!authManager.isAdmin()){authManager.hideAdminButtons();}});setInterval(()=>{if(authManager.isAdmin()){authManager.checkAuthStatus();}},60000);console.log('🔐 Système d\'authentification initialisé');